def resolve_image(name: str, category: str) -> str:
    """Cari gambar di IMAGE_MAP, fallback ke placehold.co."""
    colors = {
        "Nyeri & Demam": "ef4444",
        "Obat Batuk": "3b82f6",
        "Flu & Pilek": "06b6d4",
        "Lambung & Maag": "10b981",
        "Pencernaan & Diare": "f59e0b",
        "Suplemen": "eab308",
        "Alergi & Gatal": "8b5cf6",
        "Obat Kulit & Luka": "ec4899",
        "Antijamur & Kulit": "14b8a6",
        "Obat Oles Nyeri": "f97316",
        "Mata & Telinga": "0ea5e9",
        "Mulut & Tenggorokan": "d946ef",
        "Herbal & Tradisional": "84cc16",
        "Perawatan Hidung & Pernapasan": "64748b",
    }
    # Check exact match
    if name in IMAGE_MAP:
        return f"/static/medicines/{IMAGE_MAP[name]}"
    # Check partial match
    for key, fname in IMAGE_MAP.items():
        if key.lower() == name.lower():
            return f"/static/medicines/{fname}"
    # Fallback placeholder
    fg = colors.get(category, "64748b")
    return f"https://placehold.co/400x300/f8fafc/{fg}?text={name[:30].replace(' ', '+')}"


def build_rows():
    rows = []
    medicines_json = []
    seen_names = set()

    for item in MEDICINES:
        name, composition, uses, side_effects, category, manufacturer, price, keywords = item
        if name in seen_names:
            continue
        seen_names.add(name)

        stock = random.randint(80, 190)
        image_url = resolve_image(name, category)

        rows.append([
            name, composition, uses, side_effects, category, manufacturer,
            "false", "true", keywords,
            "Gunakan sesuai petunjuk pada kemasan. Jika sakit berlanjut hubungi dokter.",
            price, stock, image_url
        ])
        medicines_json.append({
            "name": name, "kategori_id": [category],
            "composition": composition, "uses": uses, "side_effects": side_effects,
            "manufacturer": manufacturer, "price": price, "stock": stock, "image_url": image_url
        })

    print(f"Total unik: {len(rows)} obat")
    return rows, medicines_json


def main():
    rows, medicines_json = build_rows()

    with CSV_PATH.open("w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(HEADER)
        writer.writerows(rows)

    JSON_PATH.write_text(
        json.dumps({"medicines": medicines_json}, ensure_ascii=False, indent=2),
        encoding="utf-8"
    )
    print(f"File CSV: {CSV_PATH}")
    print(f"File JSON: {JSON_PATH}")


if __name__ == "__main__":
    main()
